private void perm(int[] a, int start, List<List<Integer>> out) {
  if (start == a.length) { out.add(Arrays.stream(a).boxed().toList()); return; }
  for (int i = start; i < a.length; i++) {
    swap(a, start, i);
    perm(a, start + 1, out);
    swap(a, start, i);
  }
}

